CREATE OR REPLACE VIEW `ENUM_TYPE_CHILD_AND_ENUM` AS
SELECT `PARENT`.`ENUM_TYPE_ID` AS `PARENT_ENUM_TYPE_ID`, `PARENT`.`PARENT_TYPE_ID` AS `PARENT_PARENT_TYPE_ID`, `PARENT`.`HAS_TABLE` AS `PARENT_HAS_TABLE`, `PARENT`.`DESCRIPTION` AS `PARENT_DESCRIPTION`, `CHILD`.`ENUM_TYPE_ID` AS `CHILD_ENUM_TYPE_ID`, `CHILD`.`HAS_TABLE` AS `CHILD_HAS_TABLE`, `CHILD`.`DESCRIPTION` AS `CHILD_DESCRIPTION`, `ENUM`.`ENUM_ID` AS `ENUM_ID`, `ENUM`.`ENUM_TYPE_ID` AS `ENUM_TYPE_ID`, `ENUM`.`ENUM_CODE` AS `ENUM_CODE`, `ENUM`.`SEQUENCE_ID` AS `SEQUENCE_ID`, `ENUM`.`DESCRIPTION` AS `DESCRIPTION`
FROM `ENUMERATION_TYPE` `PARENT`
INNER JOIN `ENUMERATION_TYPE` `CHILD` ON `PARENT`.`ENUM_TYPE_ID` = `CHILD`.`PARENT_TYPE_ID`
INNER JOIN `ENUMERATION` `ENUM` ON `CHILD`.`ENUM_TYPE_ID` = `ENUM`.`ENUM_TYPE_ID`
;

CREATE OR REPLACE VIEW `COUNTRY_TELE_CODE_AND_NAME` AS
SELECT `CT`.`TELE_CODE` AS `TELE_CODE`, `CC`.`COUNTRY_CODE` AS `COUNTRY_CODE`, `CC`.`COUNTRY_NAME` AS `COUNTRY_NAME`
FROM `COUNTRY_CODE` `CC`
INNER JOIN `COUNTRY_TELE_CODE` `CT` ON `CC`.`COUNTRY_CODE` = `CT`.`COUNTRY_CODE`
;

CREATE OR REPLACE VIEW `GEO_ASSOC_AND_GEO_FROM` AS
SELECT `GA`.`GEO_ID_TO` AS `GEO_ID_TO`, `GA`.`GEO_ASSOC_TYPE_ID` AS `GEO_ASSOC_TYPE_ID`, `GFR`.`GEO_ID` AS `GEO_ID`, `GFR`.`GEO_TYPE_ID` AS `GEO_TYPE_ID`, `GFR`.`GEO_NAME` AS `GEO_NAME`, `GFR`.`GEO_CODE` AS `GEO_CODE`, `GFR`.`GEO_SEC_CODE` AS `GEO_SEC_CODE`, `GFR`.`ABBREVIATION` AS `ABBREVIATION`, `GFR`.`WELL_KNOWN_TEXT` AS `WELL_KNOWN_TEXT`
FROM `GEO_ASSOC` `GA`
INNER JOIN `GEO` `GFR` ON `GA`.`GEO_ID` = `GFR`.`GEO_ID`
;

CREATE OR REPLACE VIEW `GEO_ASSOC_AND_GEO_TO` AS
SELECT `GA`.`GEO_ID` AS `GEO_ID_FROM`, `GA`.`GEO_ASSOC_TYPE_ID` AS `GEO_ASSOC_TYPE_ID`, `GTO`.`GEO_ID` AS `GEO_ID`, `GTO`.`GEO_TYPE_ID` AS `GEO_TYPE_ID`, `GTO`.`GEO_NAME` AS `GEO_NAME`, `GTO`.`GEO_CODE` AS `GEO_CODE`, `GTO`.`GEO_SEC_CODE` AS `GEO_SEC_CODE`, `GTO`.`ABBREVIATION` AS `ABBREVIATION`, `GTO`.`WELL_KNOWN_TEXT` AS `WELL_KNOWN_TEXT`
FROM `GEO_ASSOC` `GA`
INNER JOIN `GEO` `GTO` ON `GA`.`GEO_ID_TO` = `GTO`.`GEO_ID`
;

CREATE OR REPLACE VIEW `GEO_ASSOC_AND_GEO_TO_WITH_STATE` AS
SELECT `GA`.`GEO_ID` AS `GEO_ID_FROM`, `GA`.`GEO_ASSOC_TYPE_ID` AS `GEO_ASSOC_TYPE_ID`, `GTO`.`GEO_ID` AS `GEO_ID`, `GTO`.`GEO_TYPE_ID` AS `GEO_TYPE_ID`, `GTO`.`GEO_NAME` AS `GEO_NAME`, `GTO`.`GEO_CODE` AS `GEO_CODE`, `GTO`.`GEO_SEC_CODE` AS `GEO_SEC_CODE`, `GTO`.`ABBREVIATION` AS `ABBREVIATION`, `GTO`.`WELL_KNOWN_TEXT` AS `WELL_KNOWN_TEXT`
FROM `GEO_ASSOC` `GA`
INNER JOIN `GEO` `GTO` ON `GA`.`GEO_ID_TO` = `GTO`.`GEO_ID`
INNER JOIN `COUNTRY_ADDRESS_FORMAT` `GWS` ON `GA`.`GEO_ID` = `GWS`.`GEO_ID`
;

CREATE OR REPLACE VIEW `STATUS_VALID_CHANGE_TO_DETAIL` AS
SELECT `SVC`.`STATUS_ID` AS `STATUS_ID`, `SVC`.`STATUS_ID_TO` AS `STATUS_ID_TO`, `SVC`.`CONDITION_EXPRESSION` AS `CONDITION_EXPRESSION`, `SVC`.`TRANSITION_NAME` AS `TRANSITION_NAME`, `SI`.`STATUS_TYPE_ID` AS `STATUS_TYPE_ID`, `SI`.`STATUS_CODE` AS `STATUS_CODE`, `SI`.`SEQUENCE_ID` AS `SEQUENCE_ID`, `SI`.`DESCRIPTION` AS `DESCRIPTION`
FROM `STATUS_VALID_CHANGE` `SVC`
INNER JOIN `STATUS_ITEM` `SI` ON `SVC`.`STATUS_ID_TO` = `SI`.`STATUS_ID`
;

CREATE OR REPLACE VIEW `UOM_AND_GROUP` AS
SELECT `UOMGP`.`UOM_GROUP_ID` AS `UOM_GROUP_ID`, `UOMGP`.`UOM_ID` AS `UOM_ID`, `UOM`.`UOM_TYPE_ID` AS `UOM_TYPE_ID`, `UOM`.`ABBREVIATION` AS `ABBREVIATION`, `UOM`.`NUMERIC_CODE` AS `NUMERIC_CODE`, `UOM`.`DESCRIPTION` AS `DESCRIPTION`, `UOMTP`.`UOM_TYPE_ID` AS `TYPE_UOM_TYPE_ID`, `UOMTP`.`PARENT_TYPE_ID` AS `TYPE_PARENT_TYPE_ID`, `UOMTP`.`HAS_TABLE` AS `TYPE_HAS_TABLE`, `UOMTP`.`DESCRIPTION` AS `TYPE_DESCRIPTION`
FROM `UOM_GROUP` `UOMGP`
INNER JOIN `UOM` `UOM` ON `UOMGP`.`UOM_ID` = `UOM`.`UOM_ID`
INNER JOIN `UOM_TYPE` `UOMTP` ON `UOM`.`UOM_TYPE_ID` = `UOMTP`.`UOM_TYPE_ID`
;

CREATE OR REPLACE VIEW `UOM_AND_TYPE` AS
SELECT `UOM`.`UOM_ID` AS `UOM_ID`, `UOM`.`UOM_TYPE_ID` AS `UOM_TYPE_ID`, `UOM`.`ABBREVIATION` AS `ABBREVIATION`, `UOM`.`NUMERIC_CODE` AS `NUMERIC_CODE`, `UOM`.`DESCRIPTION` AS `DESCRIPTION`, `UOMTP`.`UOM_TYPE_ID` AS `TYPE_UOM_TYPE_ID`, `UOMTP`.`PARENT_TYPE_ID` AS `TYPE_PARENT_TYPE_ID`, `UOMTP`.`HAS_TABLE` AS `TYPE_HAS_TABLE`, `UOMTP`.`DESCRIPTION` AS `TYPE_DESCRIPTION`
FROM `UOM` `UOM`
INNER JOIN `UOM_TYPE` `UOMTP` ON `UOM`.`UOM_TYPE_ID` = `UOMTP`.`UOM_TYPE_ID`
;

CREATE OR REPLACE VIEW `PORTAL_PAGE_AND_USER_LOGIN` AS
SELECT `PP`.`PORTAL_PAGE_ID` AS `PORTAL_PAGE_ID`, `PP`.`SECURITY_GROUP_ID` AS `SECURITY_GROUP_ID`, `PP`.`PARENT_PORTAL_PAGE_ID` AS `PARENT_PORTAL_PAGE_ID`, `UG`.`USER_LOGIN_ID` AS `USER_LOGIN_ID`, `UG`.`FROM_DATE` AS `FROM_DATE`, `UG`.`THRU_DATE` AS `THRU_DATE`
FROM `PORTAL_PAGE` `PP`
INNER JOIN `USER_LOGIN_SECURITY_GROUP` `UG` ON `PP`.`SECURITY_GROUP_ID` = `UG`.`GROUP_ID`
;

CREATE OR REPLACE VIEW `PORTAL_PAGE_PORTLET_VIEW` AS
SELECT `PPGPTLT`.`PORTAL_PAGE_ID` AS `PORTAL_PAGE_ID`, `PPGPTLT`.`PORTAL_PORTLET_ID` AS `PORTAL_PORTLET_ID`, `PPGPTLT`.`PORTLET_SEQ_ID` AS `PORTLET_SEQ_ID`, `PPGPTLT`.`COLUMN_SEQ_ID` AS `COLUMN_SEQ_ID`, `PPGPTLT`.`SEQUENCE_NUM` AS `SEQUENCE_NUM`, `PTLT`.`PORTLET_NAME` AS `PORTLET_NAME`, `PTLT`.`SCREEN_NAME` AS `SCREEN_NAME`, `PTLT`.`SCREEN_LOCATION` AS `SCREEN_LOCATION`, `PTLT`.`EDIT_FORM_NAME` AS `EDIT_FORM_NAME`, `PTLT`.`EDIT_FORM_LOCATION` AS `EDIT_FORM_LOCATION`, `PTLT`.`DESCRIPTION` AS `DESCRIPTION`, `PTLT`.`SCREENSHOT` AS `SCREENSHOT`, `PTLT`.`SECURITY_SERVICE_NAME` AS `SECURITY_SERVICE_NAME`, `PTLT`.`SECURITY_MAIN_ACTION` AS `SECURITY_MAIN_ACTION`
FROM `PORTAL_PAGE_PORTLET` `PPGPTLT`
INNER JOIN `PORTAL_PORTLET` `PTLT` ON `PPGPTLT`.`PORTAL_PORTLET_ID` = `PTLT`.`PORTAL_PORTLET_ID`
;

CREATE OR REPLACE VIEW `PORTAL_PAGE_AND_PORTLET` AS
SELECT `PPP`.`SEQUENCE_NUM` AS `PORTLET_SEQUENCE_NUM`, `PP`.`PORTAL_PAGE_ID` AS `PORTAL_PAGE_ID`, `PP`.`PORTAL_PAGE_NAME` AS `PORTAL_PAGE_NAME`, `PP`.`DESCRIPTION` AS `DESCRIPTION`, `PP`.`OWNER_USER_LOGIN_ID` AS `OWNER_USER_LOGIN_ID`, `PP`.`ORIGINAL_PORTAL_PAGE_ID` AS `ORIGINAL_PORTAL_PAGE_ID`, `PP`.`PARENT_PORTAL_PAGE_ID` AS `PARENT_PORTAL_PAGE_ID`, `PP`.`SEQUENCE_NUM` AS `SEQUENCE_NUM`, `PP`.`SECURITY_GROUP_ID` AS `SECURITY_GROUP_ID`, `PP`.`HELP_CONTENT_ID` AS `HELP_CONTENT_ID`, `PPP`.`PORTAL_PORTLET_ID` AS `PORTAL_PORTLET_ID`, `PPP`.`PORTLET_SEQ_ID` AS `PORTLET_SEQ_ID`, `PPP`.`COLUMN_SEQ_ID` AS `COLUMN_SEQ_ID`
FROM `PORTAL_PAGE` `PP`
INNER JOIN `PORTAL_PAGE_PORTLET` `PPP` ON `PP`.`PORTAL_PAGE_ID` = `PPP`.`PORTAL_PAGE_ID`
;

CREATE OR REPLACE VIEW `TESTING_VIEW_PKS` AS
SELECT `TST`.`TESTING_TYPE_ID` AS `TESTING_TYPE_ID`, `TST`.`DESCRIPTION` AS `DESCRIPTION`, `TSTSUB`.`SUBTYPE_DESCRIPTION` AS `SUBTYPE_DESCRIPTION`
FROM `TESTING_TYPE` `TST`
INNER JOIN `TESTING_SUBTYPE` `TSTSUB` ON `TST`.`TESTING_TYPE_ID` = `TSTSUB`.`TESTING_TYPE_ID`
;

CREATE OR REPLACE VIEW `TESTING_NODE_AND_MEMBER` AS
SELECT `TN`.`TESTING_NODE_ID` AS `TESTING_NODE_ID`, `TN`.`PRIMARY_PARENT_NODE_ID` AS `PRIMARY_PARENT_NODE_ID`, `TN`.`DESCRIPTION` AS `DESCRIPTION`, `TNM`.`TESTING_ID` AS `TESTING_ID`, `TNM`.`FROM_DATE` AS `FROM_DATE`, `TNM`.`THRU_DATE` AS `THRU_DATE`, `TNM`.`EXTEND_FROM_DATE` AS `EXTEND_FROM_DATE`, `TNM`.`EXTEND_THRU_DATE` AS `EXTEND_THRU_DATE`
FROM `TESTING_NODE` `TN`
INNER JOIN `TESTING_NODE_MEMBER` `TNM` ON `TN`.`TESTING_NODE_ID` = `TNM`.`TESTING_NODE_ID`
;

CREATE OR REPLACE VIEW `TESTING_CRYPTO_RAW_VIEW` AS
SELECT `TC`.`TESTING_CRYPTO_ID` AS `TESTING_CRYPTO_ID`, `TC`.`TESTING_CRYPTO_TYPE_ID` AS `TESTING_CRYPTO_TYPE_ID`, `TC`.`UNENCRYPTED_VALUE` AS `UNENCRYPTED_VALUE`, `TC`.`ENCRYPTED_VALUE` AS `ENCRYPTED_VALUE`, `TC`.`SALTED_ENCRYPTED_VALUE` AS `SALTED_ENCRYPTED_VALUE`
FROM `TESTING_CRYPTO` `TC`
